impl Emitable for Inet6DevConf {
    fn buffer_len(&self) -> usize {
        size_of::<Inet6DevConfBuffer>()
    }

    fn emit(&self, buffer: &mut [u8]) {
        let raw = Inet6DevConfBuffer::from(self);
        buffer.copy_from_slice(raw.as_bytes());
    }
}

